package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            People people, Out<Person> personOut) throws PersonNotFoundException {
        Person person = null;
        try {
            person = people.find(sheetId, Long.parseLong(personId));
        } catch (NumberFormatException e) {
            // not an id this app assigned
        }
        if (person == null) {
            throw new PersonNotFoundException(personId);
        }
        personOut.set(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person));
    }
}

    /** Adds a hold to the person. The person's version is left as it is — holding is not an edit of
     *  the person form. */
    public void addHold(Person person, Person.Hold hold) {
        jdbc.update("INSERT INTO person_hold (sheet_id, person_id, from_date, to_date, set_on) VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
                person.getSheetId(), person.getId(), java.sql.Date.valueOf(hold.from()),
                hold.to() == null ? null : java.sql.Date.valueOf(hold.to()), person.getSheetId());
        person.getHolds().add(hold);
    }

    /** Saves the person over the version it was loaded at, moving it on by one, with any grade the
     *  edit recorded; false (nothing written) when someone else has saved the person since. */
    public boolean save(Person person) {
-- A person's holds, each from a date to an optional to-date (open-ended when null), in the order
-- they were added (seq). A person may have several over time. Only their OPEN (and PENDING) claims
-- dated within a hold, and not bound by a statement, are left out of the live totals. A person
-- held before holds had dates is held from the beginning of time.
CREATE TABLE person_hold (
    seq       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(200) NOT NULL,
    person_id BIGINT       NOT NULL,
    from_date DATE         NOT NULL,
    to_date   DATE
);
INSERT INTO person_hold (sheet_id, person_id, from_date, to_date)
    SELECT sheet_id, id, DATE '0001-01-01', NULL FROM person WHERE held;
ALTER TABLE person DROP COLUMN held;

